      "full_text" : "#茹露逼\n居然玩线下举报剧本\n依旧老三样\n时间女儿装逼缺一不可\n加上\n茹露逼式语病台词\n每句话都是主谓宾结构错误\n还夹杂哈伊哈啊叫床声\n激动处狂喷三字经\n结结巴巴茹口吃\n听得人真累呀\n\n你个史上最蠢杀猪盘\n不要笑丝人😄\n\n茹露逼认知残疾弱反馈\n不知天高地厚\n弱智法盲口吃装逼犯\n恶人先告状不得好Si https://t.co/UOnZ3hDetq",
