      "full_text" : "😂听听中推聊天唱歌地板\n茹露逼的发言总结\n主谓宾也搞不清\n小笨鸡质疑它房子没影子老师多\n它居然激动地说国内外都有房\n说英国护照值5,000,000英镑\n国内外都有房子\n怎么这么多年不回国的\n也不打赏\n这谈吐一听就知\n是个十八线小村女\n鳏寡孤独穷\n装逼犯绿茶婊 https://t.co/iZqFKA8CBX",
      "lang" : "zh",
