      "full_text" : "RT @Pathusa: 我去，被刚看到的新闻震惊到了。\n\n洛杉矶中餐厅“一面之缘”的老板被曾经雇佣过的华人非法移民以非法用工等为由索赔80万美元……\n\n之前就听说有人以“非法用工”为由举报自己的雇主以获取“U、T签证”。",
