      "full_text" : "有人奇怪华川粉为什么那么多，他们对川普的毫无道德底线满不在乎吗？\n\n以我的观察，在中国，十男九嫖，只要他有条件。道德在华人社会是奢侈品，理解了这点就不会奇怪这些人为啥喜欢川普这种性侵犯了。",
