      "full_text" : "临近大选,很多华人说达顿反华.我一直不明白这些人的心理: 你那么爱国,为什么还那么努力的出国呢?留在国内建设祖国不好吗?问了周围很多爱国华人这个问题,却没有一个人给我答案.我想只能有两种解释:一种是虚伪至极,口是心非的.还有一种就是重度精神分裂的.我是真心想了解这些人的心理,可惜他们都不回答.",
