      "possibly_sensitive" : false,
      "created_at" : "Thu Jul 02 15:45:53 +0000 2026",
      "favorited" : false,
      "full_text" : "#大猫玩造谣玩话术\n\n大猫\n你看了吗\n竟然如此无知失态\n\n首先\n大猫造谣德先生是嘉宝莉的女朋友\n\n指责德先生没把收到的假裸照转发给嘉宝莉作为\n指控茹露逼的证据\n故意再次传播二次伤害\n用心险恶\n\n德先生出于保护女网友\n一时语塞\n\n德先生选择不传谣和无视\n显示出他的\n边界感\n同理心\n责任心\n和社会伦理道德 https://t.co/dvJYeHdEsP",
