      "full_text" : "#大猫玩造谣玩话术\n\n客观上沦为骗子帮凶\n\n他首先造谣嘉宝莉说做一个打茹露逼五年计划\n\n被否认后说嘉宝莉永远打茹露逼\n\n故意或者无意混淆无限期和永远\n\n说明大猫\n阅读相关文本少\n经常接触法律行政公文的人\n知道无限期与永远是不同概念\n相关经历少\n没有接触过正式通知处分决定合同等\n按照日常语感理解 https://t.co/pGaKEzpYNV",
