      "favorited" : false,
      "full_text" : "#茹露逼发裸照假币杀猪盘\n\n剧本又翻车\n\n打架时怎么\n\n不称呼自己是 “如歌”了\n\n“如歌”是茹露逼的假人设\n\n打架时的茹露逼才是真人\n\n #假人设真情绪  NPD\n\n茹露逼说了多少个 “我”字\n\n一个极端自私自利的弱反馈弱智\n\n剧本烂演技差\n\n茹露逼分居分房睡还是\n\n鳏寡孤独穷十八线小村女\n\n到处发裸照找下家 https://t.co/moPe2STyPA",
