      "created_at" : "Sat Jun 27 19:47:41 +0000 2026",
      "favorited" : false,
      "full_text" : "⚠️史上最蠢杀猪盘\n#茹露逼茹智障\n事实逻辑观点偏差\n空间叫床鬼哭狼嚎吼high歌\n高潮迭起Mountain Top\n用上央视否定音乐属性\n茹露逼的智障认知\n金盆子里的屎就不是屎\n语境误差逻辑链锻裂\n五音不全\n口含过期腌萝卜\n老娘们公鸭嗓\n老烂黄瓜装嫩刷绿漆\n装逼卖萌真噁心🤮 https://t.co/SNiiPC810G",
