      "full_text" : "#小村女茹露逼\n臭大街还装逼\n冒充英国贵妇 \n原来是个娼妓 \n大脸露腿露逼\n丑天际不自知\n背驼眼花耳背\n破锣腌萝卜嗓\n嚎嗨歌叫床浪\n再狂叫也没用\n杀猪盘靠这货\n盘子被砸歇菜\n素质差没人气\n勾搭露腿露逼\n脑不好还蠢坏\n冒充网友骗粉\n不是咿啊叫床\n就是张冠李戴\n做喷子喷粪忙\n辱骗打官司亡",
