      "full_text" : "中国政府现存债务170万亿，按照3%利率，每年债务利息5万亿，\n\n中国gdp每年100万亿，也就是说，中国每年gdp的5%是需要用来还债券利息的。\n\n如果有一笔债务违约，意味着刚性兑付的中国政府陷入信用破产，中国各大银行的170万亿债券资产成为废纸，直接将会陷入金融危机。\n\n为国家化债而努力吧，老铁们",
