      "full_text" : "美股密集上链的背后是老美通过加密货币吸血全球的野望\n\n让其他国家的资本更容易流入美国的资本市场\n\n这种情况下东大必然需要出手进行反制\n\n与usdc 等相抗衡的离岸人民币稳定币一定会加速出现\n\n进一步推动人民币全球化和一带一路战略\n\n而这个整个华人金融业接下来最大的机会\n\n不仅仅是币圈",
